{"path":"/root/solve.py","content":"#!/usr/bin/env python3
import csv
import json
from pathlib import Path

ROOT = Path('/root')

ASSUMPTIONS = {
    "dispatches_per_year_6_day": 60,
    "dispatches_per_year_12_day": 30,
    "days_per_dispatch_6_day": 6,
    "days_per_dispatch_12_day": 12,
    "switch_threshold_usd": 11000,
    "override_rule": "highest numeric approved revision with non-empty active_clinics, else default_active_clinics",
    "suspension_rule": "exclude hold campaigns",
}

CAMPAIGN_KEYS = [
    "campaign_id",
    "campaign_name",
    "active_clinics",
    "drug_cost_per_1000_doses_usd",
    "doses_per_day",
    "crate_tier",
    "crate_cost_usd",
    "payment_per_dispatch_per_clinic_usd",
    "annual_drug_cost_6_day_usd",
    "annual_drug_cost_12_day_usd",
    "annual_crate_cost_6_day_usd",
    "annual_crate_cost_12_day_usd",
    "annual_revenue_6_day_usd",
    "annual_revenue_12_day_usd",
    "annual_margin_6_day_usd",
    "annual_margin_12_day_usd",
    "annual_margin_difference_12_minus_6_usd",
]


def read_csv(name):
    with (ROOT / name).open(newline='') as f:
        return list(csv.DictReader(f))


def as_float(value):
    return float(value)


def as_int(value):
    return int(float(value))


def currency(value):
    return round(float(value) + 0.0, 2)


def iter_manifest_campaigns(manifest):
    if isinstance(manifest, list):
        for item in manifest:
            if isinstance(item, dict) and "campaigns" in item:
                yield from item["campaigns"]
            else:
                yield item
    elif isinstance(manifest, dict):
        if "campaigns" in manifest:
            yield from manifest["campaigns"]
        elif "regions" in manifest:
            for region in manifest["regions"]:
                yield from region.get("campaigns", [])
        else:
            for value in manifest.values():
                if isinstance(value, list):
                    for item in value:
                        if isinstance(item, dict) and "campaign_id" in item:
                            yield item
                        elif isinstance(item, dict) and "campaigns" in item:
                            yield from item["campaigns"]


def latest_billing_by_label(rows):
    active_rows = [r for r in rows if r.get("status") == "active"]
    by_label = {}
    for row in active_rows:
        label = row.get("campaign_label", "")
        if not label:
            continue
        if label not in by_label or row.get("cycle_tag", "") > by_label[label].get("cycle_tag", ""):
            by_label[label] = row
    return by_label


def active_clinic_overrides(rows):
    best = {}
    for row in rows:
        if row.get("state") != "approved":
            continue
        revision = (row.get("revision") or "").strip()
        active_clinics = (row.get("active_clinics") or "").strip()
        if not revision or not active_clinics:
            continue
        try:
            revision_number = int(float(revision))
            active_clinic_count = as_int(active_clinics)
        except ValueError:
            continue
        campaign_id = row.get("campaign_id", "")
        if campaign_id and (campaign_id not in best or revision_number > best[campaign_id][0]):
            best[campaign_id] = (revision_number, active_clinic_count)
    return {campaign_id: value[1] for campaign_id, value in best.items()}


def billing_for_campaign(campaign, billing_by_label):
    labels = [campaign.get("campaign_name", "")]
    labels.extend(campaign.get("alias_labels") or [])
    matches = [billing_by_label[label] for label in labels if label in billing_by_label]
    if not matches:
        raise ValueError(f"No active billing row found for {campaign.get('campaign_id')}")
    return max(matches, key=lambda row: row.get("cycle_tag", ""))


def campaign_analysis(campaign, crate_costs, billing_by_label, overrides):
    campaign_id = campaign["campaign_id"]
    active_clinics = overrides.get(campaign_id, as_int(campaign["default_active_clinics"]))
    crate_tier = campaign["crate_tier"]
    crate_cost_usd = as_float(crate_costs[crate_tier])
    payment = as_float(billing_for_campaign(campaign, billing_by_label)["payment_per_dispatch_per_clinic_usd"])
    drug_cost_per_1000 = as_float(campaign["drug_cost_per_1000_doses_usd"])
    doses_per_day = as_float(campaign["doses_per_day"])

    def model(days_per_dispatch, dispatches_per_year):
        annual_drug_cost = drug_cost_per_1000 * active_clinics * doses_per_day * days_per_dispatch * dispatches_per_year / 1000
        annual_crate_cost = crate_cost_usd * dispatches_per_year
        annual_revenue = payment * active_clinics * dispatches_per_year
        annual_margin = annual_revenue - annual_drug_cost - annual_crate_cost
        return annual_drug_cost, annual_crate_cost, annual_revenue, annual_margin

    drug_6, crate_6, revenue_6, margin_6 = model(6, 60)
    drug_12, crate_12, revenue_12, margin_12 = model(12, 30)

    result = {
        "campaign_id": campaign_id,
        "campaign_name": campaign["campaign_name"],
        "active_clinics": active_clinics,
        "drug_cost_per_1000_doses_usd": currency(drug_cost_per_1000),
        "doses_per_day": as_int(doses_per_day),
        "crate_tier": crate_tier,
        "crate_cost_usd": currency(crate_cost_usd),
        "payment_per_dispatch_per_clinic_usd": currency(payment),
        "annual_drug_cost_6_day_usd": currency(drug_6),
        "annual_drug_cost_12_day_usd": currency(drug_12),
        "annual_crate_cost_6_day_usd": currency(crate_6),
        "annual_crate_cost_12_day_usd": currency(crate_12),
        "annual_revenue_6_day_usd": currency(revenue_6),
        "annual_revenue_12_day_usd": currency(revenue_12),
        "annual_margin_6_day_usd": currency(margin_6),
        "annual_margin_12_day_usd": currency(margin_12),
        "annual_margin_difference_12_minus_6_usd": currency(margin_12 - margin_6),
    }
    return {key: result[key] for key in CAMPAIGN_KEYS}


def main():
    manifest = json.loads((ROOT / 'campaign_manifest.json').read_text())
    crate_rows = read_csv('crate_cost.csv')
    billing_rows = read_csv('billing.csv')
    override_rows = read_csv('location_overrides.csv')
    suspension_rows = read_csv('suspensions.csv')

    crate_costs = {row['crate_tier']: row['crate_cost_usd'] for row in crate_rows}
    billing_by_label = latest_billing_by_label(billing_rows)
    overrides = active_clinic_overrides(override_rows)
    held_campaign_ids = {
        row.get('campaign_id')
        for row in suspension_rows
        if row.get('suspension_status') == 'hold'
    }

    retained_campaigns = [
        campaign for campaign in iter_manifest_campaigns(manifest)
        if campaign.get('analysis_flag') == 'review' and campaign.get('campaign_id') not in held_campaign_ids
    ]

    campaigns = [campaign_analysis(c, crate_costs, billing_by_label, overrides) for c in retained_campaigns]
    campaigns.sort(key=lambda row: row['campaign_id'])

    total_6 = currency(sum(row['annual_margin_6_day_usd'] for row in campaigns))
    total_12 = currency(sum(row['annual_margin_12_day_usd'] for row in campaigns))
    total_difference = currency(total_12 - total_6)
    absolute_difference = currency(abs(total_difference))
    decision = 'move_to_12_day' if absolute_difference < ASSUMPTIONS['switch_threshold_usd'] else 'keep_6_day'

    output = {
        "assumptions": ASSUMPTIONS,
        "campaigns": campaigns,
        "totals": {
            "total_annual_margin_6_day_usd": total_6,
            "total_annual_margin_12_day_usd": total_12,
            "total_annual_margin_difference_12_minus_6_usd": total_difference,
            "absolute_total_margin_difference_usd": absolute_difference,
        },
        "recommendation": {
            "decision": decision,
            "justification": (
                f"Absolute total annual margin difference is ${absolute_difference:,.2f}; "
                f"threshold is ${ASSUMPTIONS['switch_threshold_usd']:,.2f}, so decision is {decision}."
            ),
        },
    }

    (ROOT / 'vaxcrate_analysis.json').write_text(json.dumps(output, indent=2) + '\n')

    summary_lines = [
        "# VaxCrate Dispatch Analysis",
        f"Total 6-day annual margin: ${total_6:,.2f}",
        f"Total 12-day annual margin: ${total_12:,.2f}",
        f"Absolute total margin difference: ${absolute_difference:,.2f}",
        f"Decision: {decision}",
        f"Justification: absolute difference ${absolute_difference:,.2f} is {'below' if absolute_difference < ASSUMPTIONS['switch_threshold_usd'] else 'at or above'} the ${ASSUMPTIONS['switch_threshold_usd']:,.2f} threshold.",
    ]
    (ROOT / 'vaxcrate_summary.md').write_text('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()
","cross_profile":false}

